@app.route('/health', methods=['GET'])
def health_check():
    """
    Health check endpoint for Docker and monitoring.
    Verifies connectivity to all dependencies.
    """
    health_status = {
        'status': 'healthy',
        'services': 'redirect-services',
        'timestamp': datetime.now().isoformat(),
        'checks': {}
    }

    overall_healthy = True

    # Check PostgreSQL connection
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("SELECT 1")
        cursor.close()
        conn.close()
        health_status['checks']['database'] = 'connected'
    except Exception as e:
        health_status['checks']['database'] = f'failed: {str(e)}'
        overall_healthy = False

    # Check Redis connection
    try:
        redis_client.ping()
        health_status['checks']['redis'] = 'connected'
    except Exception as e:
        health_status['checks']['redis'] = f'failed: {str(e)}'
        overall_healthy = False

    # Check RabbitMQ connection
    try:
        click_tracker.channel.basic_qos(prefetch_count=1)
        health_status['checks']['rabbitmq'] = 'connected'
    except Exception as e:
        health_status['checks']['rabbitmq'] = f'degraded: {str(e)}'
        # overall_healthy = False

    if not overall_healthy:
        health_status['status'] = 'unhealthy'
        return jsonify(health_status), 503

    return jsonify(health_status), 200


@app.route('/<short_code>', methods=['GET'])
def redirect_to_url(short_code: str):
    """
    Main redirect endpoint - the core functionality.

    Flow:
    1. Check Redis cache (fastest path)
    2. If cache miss, query PostgreSQL Replica
    3. Validate URL is active and not expired
    4. Cache result for future requests
    5. Track click event asynchronously via RabbitMQ
    6. Redirect user to original URL

    Args:
        short_code: The shortened URL code (e.g., "a3Xk2")

    Returns:
        301 redirect to original URL or error response
    """

    # STEP 1: Check Redis cache first (hot path)
    original_url = cache_manager.get_url(short_code)

    # STEP 2: Cache miss - query database (cold path)
    if not original_url:
        try:
            conn = get_db_connection()
            cursor = conn.cursor()

            cursor.execute("""
                SELECT url, status, expiration_time 
                FROM urls 
                WHERE short_url = %s
            """, (short_code,))

            result = cursor.fetchone()

            if not result:
                cursor.close()
                conn.close()
                return jsonify({
                    'error': 'URL not found',
                    'short_code': short_code
                }), 404

            original_url, status, expiration_time = result

            # STEP 3: Validate URL status
            if status != 'active':
                cursor.close()
                conn.close()
                return jsonify({
                    'error': 'URL is disabled',
                    'short_code': short_code,
                    'status': status
                }), 410

            # Check expiration
            if expiration_time and datetime.now() > expiration_time:
                cursor.close()
                conn.close()
                return jsonify({
                    'error': 'URL has expired',
                    'short_code': short_code,
                    'expired_at': expiration_time.isoformat()
                }), 410

            # STEP 4: Cache the result for future requests
            cache_manager.set_url(short_code, original_url)

            cursor.close()
            conn.close()

        except Exception as e:
            return jsonify({
                'error': 'Database error',
                'details': str(e)
            }), 500

    # STEP 5: Track click event asynchronously
    try:
        click_data = {
            'short_url': short_code,
            'clicked_at': datetime.now().isoformat(),
            'user_agent': request.headers.get('User-Agent', 'Unknown'),
            'ip_address': request.remote_addr,
            'referrer': request.headers.get('Referer')
        }

        click_tracker.track_click(click_data)
    except Exception as e:
        # Log error but don't fail the redirect
        print(f"Warning: Failed to track click: {e}")

    # STEP 6: Redirect to original URL
    return redirect(original_url, code=301)  # 301 = Permanent redirect


@app.route('/stats/<short_code>', methods=['GET'])
def get_stats(short_code: str):
    """
    Get basic statistics for a short URL.

    Returns:
        {
            "short_url": "http://short.url/a3Xk2",
            "original_url": "https://example.com",
            "clicks": 1547,
            "created_at": "2025-01-20T10:30:00",
            "last_accessed": "2025-01-20T14:22:00",
            "status": "active"
        }
    """
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        cursor.execute("""
            SELECT url, clicks, created_at, last_accessed, status, created_by
            FROM urls
            WHERE short_url = %s
        """, (short_code,))

        result = cursor.fetchone()

        if not result:
            cursor.close()
            conn.close()
            return jsonify({'error': 'URL not found'}), 404

        url, clicks, created_at, last_accessed, status, created_by = result

        cursor.close()
        conn.close()

        return jsonify({
            'short_url': f"{Config.BASE_URL}{short_code}",
            'original_url': url,
            'clicks': clicks,
            'created_at': created_at.isoformat() if created_at else None,
            'last_accessed': last_accessed.isoformat() if last_accessed else None,
            'status': status,
            'created_by': created_by
        }), 200

    except Exception as e:
        return jsonify({
            'error': 'Failed to retrieve statistics',
            'details': str(e)
        }), 500


