@app.route('/analytics/<short_code>/timeseries', methods=['GET'])
def get_timeseries(short_code: str):
    """
    Get click data over time (time-series analysis).

    Query params:
    - interval: 'hour', 'day', 'week' (default: 'day')
    - days: number of days to look back (default: 7)

    Example: GET /analytics/a3Xk2/timeseries?interval=hour&days=7

    Returns:
        {
            "short_url": "a3Xk2",
            "interval": "hour",
            "days": 7,
            "data": [
                {"time_bucket": "2025-01-20 14:00:00", "clicks": 45},
                {"time_bucket": "2025-01-20 15:00:00", "clicks": 67}
            ]
        }
    """
    try:
        interval = request.args.get('interval', 'day')
        days = int(request.args.get('days', 7))

        # Validate interval
        if interval not in ['hour', 'day', 'week']:
            return jsonify({
                'error': 'Invalid interval',
                'valid_values': ['hour', 'day', 'week']
            }), 400

        # Validate days
        if days < 1 or days > 365:
            return jsonify({
                'error': 'Days must be between 1 and 365'
            }), 400

        data = analytics_service.get_clicks_over_time(short_code, interval, days)

        return jsonify({
            'short_url': short_code,
            'interval': interval,
            'days': days,
            'data_points': len(data),
            'data': data
        }), 200
    except Exception as e:
        return jsonify({
            'error': 'Failed to retrieve time-series data',
            'details': str(e)
        }), 500


