@app.route('/analytics/top-urls', methods=['GET'])
def get_top_urls():
    """
    Get most popular URLs.

    Query params:
    - limit: number of URLs (default: 10)
    - days: only count recent clicks (optional)

    Example: GET /analytics/top-urls?limit=20&days=30

    Returns:
        {
            "limit": 20,
            "days": 30,
            "urls": [
                {"short_url": "a3Xk2", "url": "https://...", "clicks": 5432},
                ...
            ]
        }
    """
    try:
        limit = int(request.args.get('limit', 10))
        days = request.args.get('days')
        days = int(days) if days else None

        if limit < 1 or limit > 100:
            return jsonify({
                'error': 'Limit must be between 1 and 100'
            }), 400

        if days and (days < 1 or days > 365):
            return jsonify({
                'error': 'Days must be between 1 and 365'
            }), 400

        top_urls = analytics_service.get_top_urls(limit, days)

        return jsonify({
            'limit': limit,
            'days': days,
            'count': len(top_urls),
            'urls': top_urls
        }), 200
    except Exception as e:
        return jsonify({
            'error': 'Failed to retrieve top URLs',
            'details': str(e)
        }), 500


